--
-- Aquest és el punt zero de la cadena. Els valors NO es deriven de cap partida:
-- són els publicats a l'edició 199 i s'hereten tal qual. A partir
-- d'aquí, tot BARRUF es calcula rejugant els campionats que computen.
--
-- NO editeu aquest fitxer a mà: torneu a executar el generador.
-- =============================================================================

BEGIN;

-- -----------------------------------------------------------------------------
-- Temporades
-- -----------------------------------------------------------------------------
ON CONFLICT (codi) DO NOTHING;

-- -----------------------------------------------------------------------------
-- Clubs i grups de joc (27)
-- -----------------------------------------------------------------------------
ON CONFLICT (nom) DO NOTHING;

-- -----------------------------------------------------------------------------
-- Jugadors (609)
--
-- El número públic s'assigna per ordre alfabètic del nom normalitzat, de
-- manera que el generador sigui reproduïble. Un cop assignat no es canvia
-- ni es reutilitza mai.
-- -----------------------------------------------------------------------------
ON CONFLICT (numero) DO NOTHING;

-- La seqüència ha de continuar a partir de l'últim número assignat.
SELECT setval('numero_jugador_seq', 609, TRUE);

-- -----------------------------------------------------------------------------
-- Àlies: el nom tal com surt a les llistes publicades.
-- Cada campionat que s'importi n'hi anirà afegint variants.
-- -----------------------------------------------------------------------------
ON CONFLICT (alies_norm) DO NOTHING;

-- -----------------------------------------------------------------------------
-- L'edició llavor
-- -----------------------------------------------------------------------------
     'Punt de partida heretat del GENERADOR_BARRUF. Sense partides al darrere: no es pot recalcular.')
ON CONFLICT (numero) DO NOTHING;

